		$api_version = array_key_exists( 'api_version', $input )
			? (int) $input['api_version']
			: $before['api_version'];

		$merchant_id = array_key_exists( 'merchant_id', $input )
			? sanitize_text_field( trim( (string) $input['merchant_id'] ) )
			: $before['merchant_id'];

