/* On/Off Switch & Additional Badges */
.lccl-prog .lccl-gw-switch {
	display: inline-flex;
	align-items: center;
	gap: 12px;
	cursor: pointer;
	user-select: none;
}

.lccl-prog .lccl-gw-switch input {
	position: absolute;
	opacity: 0;
	width: 0;
	height: 0;
	margin: 0;
	pointer-events: none;
}

.lccl-prog .lccl-gw-switch__slider {
	position: relative;
	display: inline-block;
	width: 44px;
	height: 24px;
	background-color: #cbd5e1;
	border-radius: 9999px !important;
	transition: background-color 0.2s ease;
	flex-shrink: 0;
}

.lccl-prog .lccl-gw-switch__slider::before {
	content: "";
	position: absolute;
	height: 18px;
	width: 18px;
	left: 3px;
	bottom: 3px;
	background-color: #ffffff;
	border-radius: 50% !important;
	transition: transform 0.2s ease;
	box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
}

.lccl-prog .lccl-gw-switch input:checked + .lccl-gw-switch__slider {
	background-color: #10b981;
}

.lccl-prog .lccl-gw-switch input:checked + .lccl-gw-switch__slider::before {
	transform: translateX(20px);
}

.lccl-prog .lccl-gw-switch input:focus-visible + .lccl-gw-switch__slider {
	box-shadow: 0 0 0 2px #fff, 0 0 0 4px #10b981;
}

.lccl-prog .lccl-gw-switch__text {
	font-size: 14px;
	font-weight: 500;
	color: #1f2937;
}

.lccl-prog .lccl-gw-subnav__dot--paused {
	background: #f59e0b;
	box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.2);
}

.lccl-prog .lccl-prog__gateway-badge--muted {
	background: #f3f4f6;
	color: #4b5563;
	border: 1px solid #e5e7eb;
}"

