".lccl-bdf.lccl-bdf--donation {
	width: 100%;
	max-width: 1120px;
	margin-left: auto;
	margin-right: auto;
	margin-bottom: 48px;
	padding-bottom: 0;
	border: none;
}

.lccl-bdf.lccl-bdf--donation .lccl-donation-layout {
	display: grid;
	grid-template-columns: minmax(0, 1fr);
	gap: 24px;
	align-items: start;
}

.lccl-bdf.lccl-bdf--donation .lccl-donation__image-panel {
	display: none;
	margin: 0 !important;
	margin-top: 0 !important;
	padding: 0 !important;
	border-radius: 8px;
	overflow: hidden;
	box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
	border: 3px solid #f7f7f7;
	background: #ffffff;
	align-self: start !important;
}

.lccl-bdf.lccl-bdf--donation .lccl-donation__image {
	display: block !important;
	width: 100% !important;
	height: auto !important;
	margin: 0 !important;
	padding: 0 !important;
	border: none !important;
	object-fit: cover;
	vertical-align: top;
}

.lccl-bdf.lccl-bdf--donation .lccl-bdf__header {
	margin: 0;
	padding: 28px 28px 0;
}

.lccl-bdf.lccl-bdf--donation .lccl-bdf__title {
	font-size: 22px;
}

.lccl-bdf.lccl-bdf--donation .lccl-bdf__intro {
	margin: 0;
}

.lccl-bdf.lccl-bdf--donation .lccl-bdf__form {
	margin: 0 !important;
	margin-top: 0 !important;
	overflow: hidden;
	border: 3px solid #f7f7f7;
	scroll-margin-top: 96px;
	align-self: start !important;
}"

