	width: 18px;
	height: 18px;
	border: 2px solid rgba(51,51,51,0.25);
	border-top-color: #333333;
	border-radius: 50%;
	animation: lccl-spin 0.7s linear infinite;
	flex-shrink: 0;
}

.lccl-bdf--membership .lccl-mf__pay-spinner[hidden],
