	display: none !important;
}

.lccl-bdf--membership .lccl-mf__pay-btn.is-loading .lccl-mf__pay-spinner,
.lccl-bdf--membership .lccl-mf__pay-spinner:not([hidden]),
.lccl-bdf--donation .lccl-df__submit.is-loading .lccl-df__pay-spinner,
.lccl-bdf--donation .lccl-df__pay-spinner:not([hidden]) {
	display: inline-block !important;
}

@keyframes lccl-spin {
	to { transform: rotate(360deg); }
}

/* Secure payment note below the button */
.lccl-bdf--membership .lccl-mf__secure-note,
.lccl-bdf--donation .lccl-mf__secure-note {
	display: flex;
	align-items: center;
	gap: 6px;
	margin: 12px 0 0;
	font-size: 13px;
	color: #888888;
}"

