					missingRequired = true;
				}
			}

			if ( ! validateEmail( form, email, true ) && email && ! firstInvalid ) {
				firstInvalid = email;
				if ( ! isFilled( email ) ) {
					missingRequired = true;
				}
			}

			if ( ! validatePhone( form, phone, true ) && phone && ! firstInvalid ) {
