"

"<?php
require_once __DIR__ . '/../wp-load.php';

// Simulate an administrator user
$admin = get_user_by('login', 'admin');
if (!$admin) {
	$users = get_users(array('role' => 'administrator', 'number' => 1));
	$admin = !empty($users) ? $users[0] : null;
}
if ($admin) {
	wp_set_current_user($admin->ID);
	echo "Logged in as admin: {$admin->user_login} (ID: {$admin->ID})\n";
	echo "Can access payment dashboard: " . (LCCL_DE_Payment_Dashboard::can_access($admin) ? 'yes' : 'no') . "\n";
}

$request = new WP_REST_Request('GET', '/lccl-de/v1/payment-dashboard/transactions');
$request->set_param('tab', 'all');
$request->set_param('page', 1);
$request->set_param('per_page', 10);

$response = LCCL_DE_Payment_Dashboard::rest_transactions($request);
echo "Status: " . $response->get_status() . "\n";
$data = $response->get_data();
echo "Total items: " . $data['total'] . "\n";
echo "Stats: " . json_encode($data['stats']) . "\n";
echo "First item: " . (!empty($data['items']) ? json_encode($data['items'][0]) : 'None') . "\n";
"

